// The opening restores the reference's one-person multitasking scene.
// Props are native Hypit HTML/SVG layers; only the central IP is a raster insert.
const ink='#25201f';
const a=(x,y,w,h,fill,rx=12)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${fill}" stroke="${ink}" stroke-width="5"/>`;
const l=(x,y,xx,yy,w=5,c=ink)=>`<path d="M${x} ${y}L${xx} ${yy}" stroke="${c}" stroke-width="${w}" stroke-linecap="round" fill="none"/>`;
const circle=(x,y,r,fill,w=5)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${ink}" stroke-width="${w}"/>`;
const scribble=(x,y,w)=>`<path d="M${x} ${y}l${w} -2m-${w} 14l${w*.85} 2m-${w*.85} 14l${w*.62} -1" fill="none" stroke="${ink}" stroke-width="3" stroke-linecap="round"/>`;
function portrait(x,y){return `<g transform="translate(${x} ${y})">${circle(24,24,15,'#fff8e9',3)}<path d="M8 22q0-28 32-16l1 15-12-6-18 7" fill="#705042"/>${circle(19,25,6,'none',2)}${circle(32,25,6,'none',2)}${l(25,25,26,25,2)}<path d="M4 80l2-24q15-22 39 0l6 24" fill="#a8dbec" stroke="${ink}" stroke-width="3"/><path d="M9 52l31 5-3 10-26-4" fill="#e58b74" stroke="${ink}" stroke-width="2"/></g>`;}
function storyboard(){let s='';for(let row=0;row<2;row++)for(let col=0;col<3;col++){let x=95+col*140,y=130+row*120;s+=a(x,y,125,105,'#fffdf6',2)+portrait(x+35,y+8)+l(x+10,y+92,x+108,y+92,2);}return `<g transform="rotate(-4 295 240)">${a(70,95,460,285,'#fffaf1',4)}${a(85,105,430,17,'#eee6d4',1)}${s}</g><g transform="rotate(9 530 90)">${a(435,55,185,95,'#3b3433',4)}<path d="M440 38h180v34H440z" fill="#fffaf1" stroke="${ink}" stroke-width="5"/><path d="M450 38l25 34m20-34l25 34m20-34l25 34m20-34l25 34" stroke="${ink}" stroke-width="17"/>${l(452,105,602,105,3,'#eee6d4')}${l(452,125,550,125,3,'#eee6d4')}</g><g>${circle(560,310,48,'#292525')}${circle(554,304,31,'#ffe37a',4)}${l(565,355,565,448,7)}${l(565,448,540,464)}${l(565,448,590,464)}</g>`;}
function calendar(){let s='';for(let j=0;j<4;j++)for(let i=0;i<5;i++)s+=a(104+i*56,488+j*39,56,39,'#fffaf1',0);for(const [x,y,c]of[[112,494,'#f4a6c5'],[280,533,'#c7df7a'],[170,572,'#f4a6c5'],[336,611,'#ffe37a']])s+=a(x,y,41,25,c,1);return `<g transform="rotate(-5 255 560)"><path d="M89 430h310l25 254H66z" fill="#a7d5e6" stroke="${ink}" stroke-width="5"/>${a(89,420,310,255,'#ffe37a',6)}${a(99,473,290,185,'#fffaf1',1)}${s}${[130,185,240,295,350].map(x=>`<path d="M${x} 440v-34q0-20 14-13t2 35" fill="none" stroke="${ink}" stroke-width="5"/>`).join('')}</g>${a(20,660,85,112,'#fffaf1',2)}${scribble(30,682,53)}${a(385,488,70,100,'#fff2b3',2)}${l(396,508,407,518,3)}${l(407,518,424,495,3)}${scribble(398,539,43)}<g>${circle(110,782,66,'#e7a1be')}<path d="M110 782v-66a66 66 0 0 1 57 99z" fill="#a4d9eb" stroke="${ink}" stroke-width="4"/><path d="M110 782l57 33a66 66 0 0 1-75 30z" fill="#c7df7a" stroke="${ink}" stroke-width="4"/>${[52,85,112,145].map((h,i)=>a(205+i*42,840-h,29,h,['#ef9ab7','#a4d9eb','#c7df7a','#ffe37a'][i],1)).join('')}</g>`;}
function bubble(x,y,w,h,c,icon){return `<g>${a(x,y,w,h,c,18)}<path d="M${x+22} ${y+h}l-4 22 32-22" fill="${c}" stroke="${ink}" stroke-width="4"/>${icon==='dots'?[0,1,2].map(i=>circle(x+w*.28+i*w*.22,y+h*.5,7,'#fffaf1',2)).join(''):icon==='heart'?`<path d="M${x+w*.5} ${y+h*.73}l-25-25q-20-25 0-30 15-3 25 12 10-15 25-12 20 5 0 30z" fill="#eb7f9f" stroke="${ink}" stroke-width="3"/>`:portrait(x+12,y+8)+scribble(x+72,y+27,w-88)}</g>`;}
function comments(){return bubble(650,55,143,100,'#fffaf1','person')+bubble(825,35,132,83,'#c7df7a','dots')+bubble(995,72,130,88,'#b9a3e7','dots')+bubble(590,196,146,100,'#fffaf1','person')+bubble(1040,218,130,92,'#fffaf1','heart')+bubble(750,171,163,99,'#fffaf1','person');}
function distribution(){let s='';for(let j=0;j<3;j++)for(let i=0;i<2;i++){let x=1390+i*80,y=282+j*82;s+=a(x,y,71,70,['#9bd4e8','#f5a7c6','#ffdf71','#b6dc86','#bfa6e8','#9bd4e8'][j*2+i],2)+`<path d="M${x+10} ${y+55}l16-28 17 18 15-13v29H${x+10}z" fill="#fffaf1" stroke="${ink}" stroke-width="2"/>`;}return `<g transform="rotate(7 1465 390)">${a(1373,240,182,331,'#fffaf1',18)}${l(1425,256,1503,256,7)}${s}${l(1432,553,1500,553,6)}</g><g><path d="M1170 125q-33 0-37-27-5-25 24-32 8-40 46-31 23-25 52 4 40-5 45 30 36 2 34 30-2 27-36 26z" fill="#fffaf1" stroke="${ink}" stroke-width="5"/><path d="M1204 115V74h-21l38-39 37 39h-22v41z" fill="#ed9abd" stroke="${ink}" stroke-width="4"/></g>${a(1200,270,95,95,'#3b3433',15)}<path d="M1234 293l38 24-38 24z" fill="#ed9abd" stroke="#ed9abd" stroke-width="4"/>${a(1280,440,82,82,'#c4df7c',13)}<path d="M1307 465l29 18-29 18z" fill="#fffaf1" stroke="${ink}" stroke-width="3"/>${a(1590,290,65,68,'#efa0bd',12)}<path d="M1611 307v34m0-27l25-4v28" fill="none" stroke="${ink}" stroke-width="5"/>`;}
function business(){return `<g>${[58,96,144,183].map((h,i)=>a(1350+i*47,740-h,31,h,['#f0a0bb','#b4d98c','#a8daea','#ffe37a'][i],1)).join('')}<path d="M1335 678l55-38 42 12 58-90 63-42" fill="none" stroke="#e78a77" stroke-width="12"/><path d="M1536 515l37-7-8 38" fill="#e78a77" stroke="${ink}" stroke-width="4"/>${circle(1575,678,73,'#e4a2c3')}<path d="M1575 678v-73a73 73 0 0 1 63 109z" fill="#c9df84" stroke="${ink}" stroke-width="4"/><path d="M1575 678l63 36a73 73 0 0 1-88 30z" fill="#a3d4e7" stroke="${ink}" stroke-width="4"/>${[[1300,600],[1600,530],[1640,770],[1285,720]].map(([x,y])=>circle(x,y,25,'#ffe37a',4)+circle(x,y,16,'none',2)).join('')}</g>`;}
function foreground(){return `<svg viewBox="0 0 1700 900" class="op-fg"><g stroke-linejoin="round"><path d="M110 848q640-27 1480-2v43H110z" fill="#d9b48c" stroke="${ink}" stroke-width="4"/><g data-prop="notebook">${a(660,655,430,220,'#a69d9f',14)}<path d="M660 665q0-10 14-10h406q10 0 10 14" fill="none" stroke="#e7dcda" stroke-width="4"/><path d="M650 869h450l25 17H633z" fill="#8e8789" stroke="${ink}" stroke-width="5"/>${a(705,705,68,62,'#eea2c1',1)}${scribble(717,720,39)}${a(988,764,61,70,'#d3dc7f',1)}${scribble(998,779,36)}${a(1110,705,267,75,'#fff8ed',9)}${Array.from({length:3},(_,j)=>Array.from({length:10},(_,i)=>a(1121+i*24,716+j*17,18,12,j===2&&i>2&&i<7?'#dbd5cc':'#f1ece2',2)).join('')).join('')}</g><g transform="rotate(-7 250 835)">${[0,1,2].map((v)=>a(150+v*8,800+v*14,180,31,['#e49bb3','#b5cf91','#f1dfb1'][v],2)).join('')}</g><g data-prop="camera">${a(424,769,150,92,'#393331',12)}${a(449,751,72,30,'#393331',5)}${circle(500,813,42,'#6d6764')}${circle(500,813,29,'#292725')}${circle(500,813,18,'#8a9aa2',3)}</g><g>${a(1250,793,90,86,'#62524b',8)}${[0,1,2,3].map((v)=>l(1264+v*18,809,1245+v*30,737-v%2*20,11,['#ef9db6','#a9d7e8','#ffe078','#887199'][v])).join('')}</g><g><path d="M1390 806l12 74h74l12-74z" fill="#fff8ed" stroke="${ink}" stroke-width="5"/><ellipse cx="1439" cy="804" rx="57" ry="14" fill="#3a3331" stroke="${ink}" stroke-width="5"/><path d="M1408 840h65v23h-63z" fill="#c6aa8a"/></g><g>${[0,1,2].map(v=>a(1510+v*3,809+v*16,137,25,'#b6cd85',2)).join('')}${l(1556,812,1556,864,15,'#f5e4ad')}</g><g><ellipse cx="1565" cy="776" rx="67" ry="45" fill="#e8a0bc" stroke="${ink}" stroke-width="5"/><path d="M1530 742l-8-25 31 18m42 1l26-17-4 33" fill="#e8a0bc" stroke="${ink}" stroke-width="4"/><ellipse cx="1615" cy="777" rx="23" ry="18" fill="#efb5cc" stroke="${ink}" stroke-width="4"/>${circle(1609,777,3,ink,1)}${circle(1620,777,3,ink,1)}${circle(1595,758,4,ink,1)}${l(1540,751,1574,751,4)}${l(1528,807,1524,832,9)}${l(1583,813,1590,834,9)}</g><g data-prop="paper" transform="rotate(-12 600 854)">${a(557,820,95,65,'#fffaf1',1)}${scribble(568,837,62)}</g>${a(1120,837,65,41,'#ed9fbc',1)}${a(1205,854,63,30,'#f5dc79',1)}${l(355,856,413,820,10,'#d18c77')}${l(355,856,413,820,3)}<path d="M577 881l-16-24 18-11 15 28 13-22 14 20-13 15z" fill="#fffaf1" stroke="${ink}" stroke-width="3"/></g></svg>`;}
export function openingHtml(){return `<div class="op-font" data-font>{{font-seed}}</div><div class="op-eyebrow">一人多职 · 内容工作</div><div class="op-count">01 / 09</div><h1 class="op-title">一个人，<mark>忙成一支团队</mark></h1><div class="op-subtitle">编导、运营、客服、分发与合作，都压到一个人身上</div><div class="op-world"><svg viewBox="0 0 1700 900" class="op-bg"><defs><pattern id="op-hatch" width="11" height="11" patternUnits="userSpaceOnUse"><path d="M0 11l11-11" stroke="#332b28" opacity=".08" stroke-width="2"/></pattern></defs>${a(4,4,1692,892,'#fff9ed',26)}<path d="M55 70l450-18-19 30 65 30-55 18 60 45-69 26 65 58-43 7 46 41-93 22-329 31-67-27 34-29-51-15 30-40-37-22 37-35-43-21 39-28-40-32z" fill="#efa4c0" opacity=".85"/><path d="M80 400l385 7-28 33 45 21-30 45 37 26-45 29 31 30-36 27 43 33-67 35 28 32-405 81-5-52 29-22-36-27 43-32-30-27 25-26-27-31 36-31-20-33 32-19-23-34z" fill="#9ed5e8" opacity=".9"/><path d="M583 35l484-17-40 36 69 28-49 34 65 36-55 35 36 34-64 14 34 42-477 75-45-38 50-30-36-41 48-22-28-31 35-18-32-37z" fill="#c5dc7c" opacity=".9"/><path d="M1135 53l495-18-45 39 54 30-43 25 49 38-37 25 42 41-41 38 42 29-48 29 50 39-58 41 34 37-41 31 27 35-56 31-415 47-49-29 38-40-39-22 48-47-26-35 43-40-24-42 42-22-31-40 43-24-28-28z" fill="#bba6e3" opacity=".9"/><path d="M1220 508l410-34-30 28 42 33-39 30 46 29-36 33 27 24-34 34 38 24-43 31 37 29-47 27 35 27-70 37-374 10-45-37 30-32-35-26 35-35-28-34 41-27-23-31z" fill="#ffe078" opacity=".95"/><path d="M100 755q700-56 1510 35l-25 93H117z" fill="#e1bf99"/><g data-prop="storyboard">${storyboard()}</g><g data-prop="calendar">${calendar()}</g><g data-prop="comments">${comments()}</g><g data-prop="platforms">${distribution()}</g><g data-prop="business">${business()}</g><path d="M11 11h1678v878H11z" fill="url(#op-hatch)" pointer-events="none"/></svg><div class="op-person">{{actor}}</div>${foreground()}</div>`;}
export const openingCss=`:scope{position:relative;width:1920px;height:1080px;background:#fff;overflow:hidden;color:#211c1a}*{box-sizing:border-box}.op-font{position:absolute;opacity:0;pointer-events:none}.op-eyebrow{position:absolute;left:80px;top:42px;font-size:25px;font-weight:800;letter-spacing:2px;border-left:64px solid #efa4c0;padding-left:19px;line-height:12px}.op-count{position:absolute;right:80px;top:40px;font-size:25px;font-weight:750;letter-spacing:3px}.op-title{position:absolute;left:80px;top:102px;margin:0;font-size:80px;font-weight:900;line-height:1.3}.op-title mark{background:#efa4c0;padding:0 12px}.op-subtitle{position:absolute;left:84px;top:222px;font-size:27px;font-weight:600;color:#4d4541}.op-world{position:absolute;left:320px;top:285px;width:1280px;height:677.647059px;overflow:hidden;border-radius:22px}.op-bg,.op-fg{position:absolute;inset:0;width:100%;height:100%}.op-bg{z-index:1}.op-person{position:absolute;left:214.588235px;top:150.588235px;width:903.529412px;height:438.960784px;z-index:2}.op-person img{width:100%;height:100%;object-fit:contain}.op-fg{z-index:3;pointer-events:none}`;
export const openingSetup=`const seed=root.querySelector('[data-font]');if(seed?.firstElementChild)root.style.fontFamily=getComputedStyle(seed.firstElementChild).fontFamily;const q=s=>root.querySelector(s),clamp=x=>Math.max(0,Math.min(1,x));return function(frame){const head=clamp((frame-4)/9),title=clamp((frame-7)/9),sub=clamp((frame-12)/11),scene=clamp((frame-26)/18);q('.op-eyebrow').style.opacity=head;q('.op-count').style.opacity=head;q('.op-title').style.opacity=title;q('.op-subtitle').style.opacity=sub;const world=q('.op-world');world.style.opacity=scene;world.style.transform='translate('+((1-scene)*48)+'px,'+((1-scene)*24)+'px)';};`;
